//! | `wb_4` | n4·n5·n6 | no | 2 + 6u + 6u^2 + 2u^3 | 12u + 20u^2 + 8u^3 |
//! | `wb` | n4·n5·n6 | no | 6 + 28u + 52u^2 + 48u^3 + 22u^4 + 4u^5 | 46u + 94u^2 + 66u^3 + 22u^4 + 4u^5 |
//! | `d4` | d4 | no | 1 | u |
//! | `mzb_1` | d4·n5·n6 | no | 2 + 6u + 6u^2 + 2u^3 | 12u + 20u^2 + 8u^3 |
//! | `d5` | d5 | no | 1 | u |
//! | `mzb_2` | n4·d5·n6 | no | 2 + 6u + 6u^2 + 2u^3 | 12u + 20u^2 + 8u^3 |
//! | `mzb_3` | max{d4·n5·n6, n4·d5·n6} | no | 4 + 16u + 24u^2 + 16u^3 + 4u^4 | 28u + 52u^2 + 28u^3 + 4u^4 |
//! | `d6` | d6 | no | 1 | u |
//! | `mzb_4` | n4·n5·d6 | no | 2 + 6u + 6u^2 + 2u^3 | 12u + 20u^2 + 8u^3 |
//! | `mzb` | max{d4·n5·n6, n4·d5·n6, n4·n5·d6} | no | 6 + 28u + 52u^2 + 48u^3 + 22u^4 + 4u^5 | 46u + 94u^2 + 66u^3 + 22u^4 + 4u^5 |
//! | `h_1` | max{n1·n2·n3·d4·n5·n6, n1·n2·n3·n4·d5·n6, n1·n2·n3·n4·n5·d6} | no | 36 + 372u + 1744u^2 + 4896u^3 + 9144u^4 + 11928u^5 + 11088u^6 + 7344u^7 + 3396u^8 + 1044u^9 + 192u^10 + 16u^11 | 588u + 6156u^2 + 20896u^3 + 36548u^4 + 39280u^5 + 28484u^6 + 14656u^7 + 5420u^8 + 1396u^9 + 224u^10 + 16u^11 |
//! | `h_2` | max{d1·n2·n3·n4·n5·n6, n1·d2·n3·n4·n5·n6, n1·n2·d3·n4·n5·n6} | no | 36 + 372u + 1744u^2 + 4896u^3 + 9144u^4 + 11928u^5 + 11088u^6 + 7344u^7 + 3396u^8 + 1044u^9 + 192u^10 + 16u^11 | 588u + 6156u^2 + 20896u^3 + 36548u^4 + 39280u^5 + 28484u^6 + 14656u^7 + 5420u^8 + 1396u^9 + 224u^10 + 16u^11 |
//! | `h` | max{d1·n2·n3·n4·n5·n6, n1·d2·n3·n4·n5·n6, n1·n2·d3·n4·n5·n6, n1·n2·n3·d4·n5·n6, n1·n2·n3·n4·d5·n6, n1·n2·n3·n4·n5·d6} | no | 72 + 816u + 4232u^2 + 13280u^3 + 28080u^4 + 42144u^5 + 46032u^6 + 36864u^7 + 21480u^8 + 8880u^9 + 2472u^10 + 416u^11 + 32u^12 | 1248u + 13056u^2 + 45280u^3 + 82888u^4 + 96848u^5 + 80824u^6 + 51488u^7 + 25528u^8 + 9584u^9 + 2536u^10 + 416u^11 + 32u^12 |
//!
//! The filter computes the scale S at run time at least (1 − u)^5 times its exact value: 5
//! rounding(s), each product counting its own and both its operands', each `larger` the larger of
//! its operands'. It computes the bound as the constant times S, one more rounding: k = 5 + 1. The
//! constant is E · (1 + 2u)^k, rounded up to an `f64`.
//!
//! | Quantity | Value |
//! | --- | --- |
//! | Result | `h` |
//! | Unit error E | 1248u + 13056u^2 + 45280u^3 + 82888u^4 + 96848u^5 + 80824u^6 + 51488u^7 + 25528u^8 + 9584u^9 + 2536u^10 + 416u^11 + 32u^12 |
//! | Scale S | max{d1·n2·n3·n4·n5·n6, n1·d2·n3·n4·n5·n6, n1·n2·d3·n4·n5·n6, n1·n2·n3·d4·n5·n6, n1·n2·n3·n4·d5·n6, n1·n2·n3·n4·n5·d6} |
//! | Scale at run time | `larger(larger(larger(larger(larger(m_d1 * m_n2 * m_n3 * m_n4 * m_n5 * m_n6, m_n1 * m_d2 * m_n3 * m_n4 * m_n5 * m_n6), m_n1 * m_n2 * m_d3 * m_n4 * m_n5 * m_n6), m_n1 * m_n2 * m_n3 * m_d4 * m_n5 * m_n6), m_n1 * m_n2 * m_n3 * m_n4 * m_d5 * m_n6), m_n1 * m_n2 * m_n3 * m_n4 * m_n5 * m_d6)` |
//! | Roundings k | 6 |
//! | Constant, exactly | 1248u + 28032u^2 + 276832u^3 + 1609288u^4 + 6196784u^5 + 16834136u^6 + 33548160u^7 + 50410968u^8 + 58392976u^9 + 53184712u^10 + 38763968u^11 + 22875776u^12 + 10927872u^13 + 4151040u^14 + 1205248u^15 + 249856u^16 + 32768u^17 + 2048u^18 |
//! | Constant as an `f64` | `0x3d4380000000000e` = 5488762045857806 · 2^-95 ≈ 1.385558334732199e-13 |
//!
//! Cost: the filter is 53 `f64` operations, after 24 rounded input(s) converted to `f64`, then 24
//! magnitudes and their maxima and the bound's 31 multiplication(s); the exact path, run only when
//! the filter cannot decide, is 53 checked integer operations.

use crate::sign::Sign;
use crate::wide::{I256, I576};

use super::{decide, larger, largest_magnitude, rounded_f64, within};

/// The filter's error constant: E · (1 + 2u)^6 with E = 1248u + 13056u^2 + 45280u^3 + 82888u^4 +
/// 96848u^5 + 80824u^6 + 51488u^7 + 25528u^8 + 9584u^9 + 2536u^10 + 416u^11 + 32u^12, the result's
/// unit error (header), rounded up to an `f64`: 5488762045857806 · 2^-95.
const ERROR: f64 = f64::from_bits(0x3d43_8000_0000_000e);

/// `tpi_height`'s sign from its `f64` filter, or `None` when the filter's bound cannot certify it.
///
/// `Some(Sign::Zero)` only when the scale is zero, which makes the exact value zero; `None` also
/// for a rounded input outside its declared range.
#[inline]
#[must_use]
#[allow(
    clippy::similar_names,
    clippy::too_many_arguments,
    reason = "names, parameters and lines follow the description: one per input and step"
)]
pub fn filter(
    n1x: i128,
    n1y: i128,
    n1z: i128,
    d1: i128,
    n2x: i128,
    n2y: i128,
    n2z: i128,
    d2: i128,
    n3x: i128,
    n3y: i128,
    n3z: i128,
    d3: i128,
    n4x: i128,
    n4y: i128,
    n4z: i128,
    d4: i128,
    n5x: i128,
    n5y: i128,
    n5z: i128,
    d5: i128,
    n6x: i128,
    n6y: i128,
    n6z: i128,
    d6: i128,
) -> Option<Sign> {
    let n2y = rounded_f64(n2y, 83)?;
    let n3z = rounded_f64(n3z, 83)?;
    let a23_x_1 = n2y * n3z;
    let n2z = rounded_f64(n2z, 83)?;
    let n3y = rounded_f64(n3y, 83)?;
    let a23_x_2 = n2z * n3y;
    let a23_x = a23_x_1 - a23_x_2;
    let n3x = rounded_f64(n3x, 83)?;
    let a23_y_1 = n2z * n3x;
    let n2x = rounded_f64(n2x, 83)?;
    let a23_y_2 = n2x * n3z;
    let a23_y = a23_y_1 - a23_y_2;
    let a23_z_1 = n2x * n3y;
    let a23_z_2 = n2y * n3x;
    let a23_z = a23_z_1 - a23_z_2;
    let n1y = rounded_f64(n1y, 83)?;
    let a31_z_1 = n3x * n1y;
    let n1x = rounded_f64(n1x, 83)?;
    let a31_z_2 = n3y * n1x;
    let a31_z = a31_z_1 - a31_z_2;
    let a12_z_1 = n1x * n2y;
    let a12_z_2 = n1y * n2x;
    let a12_z = a12_z_1 - a12_z_2;
    let wa_1 = n1x * a23_x;
    let wa_2 = n1y * a23_y;
    let wa_3 = wa_1 + wa_2;
    let n1z = rounded_f64(n1z, 83)?;
    let wa_4 = n1z * a23_z;
    let wa = wa_3 + wa_4;
    let d1 = rounded_f64(d1, 125)?;
    let mza_1 = d1 * a23_z;
    let d2 = rounded_f64(d2, 125)?;
    let mza_2 = d2 * a31_z;
    let mza_3 = mza_1 + mza_2;
    let d3 = rounded_f64(d3, 125)?;
    let mza_4 = d3 * a12_z;
    let mza = mza_3 + mza_4;
    let n5y = rounded_f64(n5y, 83)?;
    let n6z = rounded_f64(n6z, 83)?;
    let b56_x_1 = n5y * n6z;
    let n5z = rounded_f64(n5z, 83)?;
    let n6y = rounded_f64(n6y, 83)?;
    let b56_x_2 = n5z * n6y;
    let b56_x = b56_x_1 - b56_x_2;
    let n6x = rounded_f64(n6x, 83)?;
    let b56_y_1 = n5z * n6x;
    let n5x = rounded_f64(n5x, 83)?;
    let b56_y_2 = n5x * n6z;
    let b56_y = b56_y_1 - b56_y_2;
    let b56_z_1 = n5x * n6y;
    let b56_z_2 = n5y * n6x;
    let b56_z = b56_z_1 - b56_z_2;
    let n4y = rounded_f64(n4y, 83)?;
    let b64_z_1 = n6x * n4y;
    let n4x = rounded_f64(n4x, 83)?;
    let b64_z_2 = n6y * n4x;
    let b64_z = b64_z_1 - b64_z_2;
    let b45_z_1 = n4x * n5y;
    let b45_z_2 = n4y * n5x;
    let b45_z = b45_z_1 - b45_z_2;
    let wb_1 = n4x * b56_x;
    let wb_2 = n4y * b56_y;
    let wb_3 = wb_1 + wb_2;
    let n4z = rounded_f64(n4z, 83)?;
    let wb_4 = n4z * b56_z;
    let wb = wb_3 + wb_4;
    let d4 = rounded_f64(d4, 125)?;
    let mzb_1 = d4 * b56_z;
    let d5 = rounded_f64(d5, 125)?;
    let mzb_2 = d5 * b64_z;
    let mzb_3 = mzb_1 + mzb_2;
    let d6 = rounded_f64(d6, 125)?;
    let mzb_4 = d6 * b45_z;
    let mzb = mzb_3 + mzb_4;
    let h_1 = mzb * wa;
    let h_2 = mza * wb;
    let h = h_1 - h_2;
    let m_n1 = largest_magnitude([n1y, n1x, n1z]);
    let m_d1 = largest_magnitude([d1]);
    let m_n2 = largest_magnitude([n2y, n2z, n2x]);
    let m_d2 = largest_magnitude([d2]);
    let m_n3 = largest_magnitude([n3z, n3y, n3x]);
    let m_d3 = largest_magnitude([d3]);
    let m_n4 = largest_magnitude([n4y, n4x, n4z]);
    let m_d4 = largest_magnitude([d4]);
    let m_n5 = largest_magnitude([n5y, n5z, n5x]);
    let m_d5 = largest_magnitude([d5]);
    let m_n6 = largest_magnitude([n6z, n6y, n6x]);
    let m_d6 = largest_magnitude([d6]);
    let scale = m_d1 * m_n2 * m_n3 * m_n4 * m_n5 * m_n6;
    let scale = larger(scale, m_n1 * m_d2 * m_n3 * m_n4 * m_n5 * m_n6);
    let scale = larger(scale, m_n1 * m_n2 * m_d3 * m_n4 * m_n5 * m_n6);
    let scale = larger(scale, m_n1 * m_n2 * m_n3 * m_d4 * m_n5 * m_n6);
    let scale = larger(scale, m_n1 * m_n2 * m_n3 * m_n4 * m_d5 * m_n6);
    let scale = larger(scale, m_n1 * m_n2 * m_n3 * m_n4 * m_n5 * m_d6);
    decide(h, ERROR, scale)
}

/// `tpi_height`'s exact value: each step in the type its certificate gives it, with checked
/// arithmetic; `None` only if a step overflowed, which the certificate rules out; `None` also for a
/// rounded input outside its declared range.
#[inline]
#[must_use]
#[allow(
    clippy::similar_names,
    clippy::too_many_arguments,
    reason = "names, parameters and lines follow the description: one per input and step"
)]
pub fn value(
    n1x: i128,
    n1y: i128,
    n1z: i128,
    d1: i128,
    n2x: i128,
    n2y: i128,
    n2z: i128,
    d2: i128,
    n3x: i128,
    n3y: i128,
    n3z: i128,
    d3: i128,
    n4x: i128,
    n4y: i128,
    n4z: i128,
    d4: i128,
    n5x: i128,
    n5y: i128,
    n5z: i128,
    d5: i128,
    n6x: i128,
    n6y: i128,
    n6z: i128,
    d6: i128,
) -> Option<I576> {
    let n2y = within(n2y, 83)?;
    let n3z = within(n3z, 83)?;
    let a23_x_1 = I256::product_i128(n2y, n3z)?;
    let n2z = within(n2z, 83)?;
    let n3y = within(n3y, 83)?;
    let a23_x_2 = I256::product_i128(n2z, n3y)?;
    let a23_x = a23_x_1.checked_sub(&a23_x_2)?;
    let n3x = within(n3x, 83)?;
    let a23_y_1 = I256::product_i128(n2z, n3x)?;
    let n2x = within(n2x, 83)?;
    let a23_y_2 = I256::product_i128(n2x, n3z)?;
    let a23_y = a23_y_1.checked_sub(&a23_y_2)?;
    let a23_z_1 = I256::product_i128(n2x, n3y)?;
    let a23_z_2 = I256::product_i128(n2y, n3x)?;
    let a23_z = a23_z_1.checked_sub(&a23_z_2)?;
    let n1y = within(n1y, 83)?;
    let a31_z_1 = I256::product_i128(n3x, n1y)?;
    let n1x = within(n1x, 83)?;
    let a31_z_2 = I256::product_i128(n3y, n1x)?;
    let a31_z = a31_z_1.checked_sub(&a31_z_2)?;
    let a12_z_1 = I256::product_i128(n1x, n2y)?;
    let a12_z_2 = I256::product_i128(n1y, n2x)?;
    let a12_z = a12_z_1.checked_sub(&a12_z_2)?;
    let wa_1 = a23_x.checked_mul_i128(n1x)?;
    let wa_2 = a23_y.checked_mul_i128(n1y)?;
    let wa_3 = wa_1.checked_add(&wa_2)?;
    let n1z = within(n1z, 83)?;
    let wa_4 = a23_z.checked_mul_i128(n1z)?;
    let wa = wa_3.checked_add(&wa_4)?;
    let d1 = within(d1, 125)?;
    let mza_1 = a23_z.resize::<5>()?.checked_mul_i128(d1)?;
    let d2 = within(d2, 125)?;
    let mza_2 = a31_z.resize::<5>()?.checked_mul_i128(d2)?;
    let mza_3 = mza_1.checked_add(&mza_2)?;
    let d3 = within(d3, 125)?;
    let mza_4 = a12_z.resize::<5>()?.checked_mul_i128(d3)?;
    let mza = mza_3.checked_add(&mza_4)?;
    let n5y = within(n5y, 83)?;
    let n6z = within(n6z, 83)?;
    let b56_x_1 = I256::product_i128(n5y, n6z)?;
    let n5z = within(n5z, 83)?;
    let n6y = within(n6y, 83)?;
    let b56_x_2 = I256::product_i128(n5z, n6y)?;
    let b56_x = b56_x_1.checked_sub(&b56_x_2)?;
    let n6x = within(n6x, 83)?;
    let b56_y_1 = I256::product_i128(n5z, n6x)?;
    let n5x = within(n5x, 83)?;
    let b56_y_2 = I256::product_i128(n5x, n6z)?;
    let b56_y = b56_y_1.checked_sub(&b56_y_2)?;
    let b56_z_1 = I256::product_i128(n5x, n6y)?;
    let b56_z_2 = I256::product_i128(n5y, n6x)?;
    let b56_z = b56_z_1.checked_sub(&b56_z_2)?;
    let n4y = within(n4y, 83)?;
    let b64_z_1 = I256::product_i128(n6x, n4y)?;
    let n4x = within(n4x, 83)?;
    let b64_z_2 = I256::product_i128(n6y, n4x)?;
    let b64_z = b64_z_1.checked_sub(&b64_z_2)?;
    let b45_z_1 = I256::product_i128(n4x, n5y)?;
    let b45_z_2 = I256::product_i128(n4y, n5x)?;
    let b45_z = b45_z_1.checked_sub(&b45_z_2)?;
    let wb_1 = b56_x.checked_mul_i128(n4x)?;
    let wb_2 = b56_y.checked_mul_i128(n4y)?;
    let wb_3 = wb_1.checked_add(&wb_2)?;
    let n4z = within(n4z, 83)?;
    let wb_4 = b56_z.checked_mul_i128(n4z)?;
    let wb = wb_3.checked_add(&wb_4)?;
    let d4 = within(d4, 125)?;
    let mzb_1 = b56_z.resize::<5>()?.checked_mul_i128(d4)?;
    let d5 = within(d5, 125)?;
    let mzb_2 = b64_z.resize::<5>()?.checked_mul_i128(d5)?;
    let mzb_3 = mzb_1.checked_add(&mzb_2)?;
    let d6 = within(d6, 125)?;
    let mzb_4 = b45_z.resize::<5>()?.checked_mul_i128(d6)?;
    let mzb = mzb_3.checked_add(&mzb_4)?;
    let h_1 = mzb.resize::<9>()?.checked_mul(&wa.resize::<9>()?)?;
    let h_2 = mza.resize::<9>()?.checked_mul(&wb.resize::<9>()?)?;
    let h = h_1.checked_sub(&h_2)?;
    Some(h)
}

/// `tpi_height`'s exact sign: the sign of [`value`], or `None` as for [`value`].
#[inline]
#[must_use]
#[allow(
    clippy::too_many_arguments,
    reason = "one parameter per input of the description"
)]
pub fn exact(
    n1x: i128,
    n1y: i128,
    n1z: i128,
    d1: i128,
    n2x: i128,
    n2y: i128,
    n2z: i128,
    d2: i128,
    n3x: i128,
    n3y: i128,
    n3z: i128,
    d3: i128,
    n4x: i128,
    n4y: i128,
    n4z: i128,
    d4: i128,
    n5x: i128,
    n5y: i128,
    n5z: i128,
    d5: i128,
    n6x: i128,
    n6y: i128,
    n6z: i128,
    d6: i128,
) -> Option<Sign> {
    value(
        n1x, n1y, n1z, d1, n2x, n2y, n2z, d2, n3x, n3y, n3z, d3, n4x, n4y, n4z, d4, n5x, n5y, n5z,
        d5, n6x, n6y, n6z, d6,
    )
    .map(|v| v.signum())
}
